import java.util.Scanner;
public class CelsiusToFahrenheit
{
	public static void main (String[] args)
	{
		//Paso 1: Definir los datos que necesitamos para este programa
		final int BASE = 32;
		final double CONVERSION_FACTOR = 9.0 / 5;
		//Paso 2: Leer el valor Celsius de entrada
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el valor en Celsius: ");
		int celsiusTemp = scan.nextInt();
		scan.close();
		//Paso 3: Calcular el equivalente en Fahrenheit del valor Celsius
		double fahrenheitTemp = celsiusTemp * CONVERSION_FACTOR + BASE;
		System.out.println("Temperatura en Celsius: " + celsiusTemp);
		System.out.println("Equivalente en Fahrenheit: " + fahrenheitTemp);
	}
}

